    @Test
    fun rowsMatchTheWebAppAndTheEndLoadsTheNextPage() {
        val first = openDetailed()
        assertEquals("one page of 50 before any scroll", 50, first.entries.size)
        assertNotNull(first.nextRow)
        compose.waitForIdle()
        assertEquals("no page asked for before the end", 50, detailed().entries.size)
        // The 00:10 entry today in the account's zone shows today's date and 12:10 AM.
        val words = DateWords(context.resources)
        val midnight = first.entries.single { it.description == "Midnight" }
        assertEquals(seed.today, midnight.start.toLocalDate())
        assertEquals("12:10 AM", settings().formatTime(midnight.start.toInstant(), midnight.start.zone))
        assertTrue("12:10 AM shows", hasNode(hasText("12:10 AM", substring = true)))
        assertTrue("today's label shows", hasNode(hasText(words.day(seed.today, seed.today), substring = true)))

        var report = first
        var scrolls = 0
        while (report.nextRow != null) {
            val before = report.entries.size
            compose.onNode(hasScrollToIndexAction()).performScrollToIndex(report.entries.size + 1)
            compose.waitUntil("the next page loads", LOAD_MS) { detailed().let { !it.loadingMore && it.entries.size > before } }
            report = detailed()
            scrolls++
        }
        assertEquals(TOTAL, report.entries.size)
        assertEquals(1, scrolls)
        val body = buildJsonObject {
            put("start_date", seed.weekStart.toString()); put("end_date", seed.weekStart.plusDays(6).toString())
            put("sort", "date"); put("dir", "desc"); put("page", 1); put("page_size", 500)
        }
        val web = account.client.send("POST", TokklTestServer.url.app("report", "entries"), body, JsonObject.serializer()).orFail("entries")
        val webRows = web["entries"]!!.jsonArray.map { it.jsonObject }.map {
            listOf(
                it["id"]!!.jsonPrimitive.long,
                OffsetDateTime.parse(it["start"]!!.jsonPrimitive.content).toInstant(),
                it["stop"]!!.jsonPrimitive.contentOrNull?.let { s -> OffsetDateTime.parse(s).toInstant() },
                it["seconds"]!!.jsonPrimitive.long,
                it["description"]!!.jsonPrimitive.content,
                it["project_name"]!!.jsonPrimitive.contentOrNull,
                it["task_name"]!!.jsonPrimitive.contentOrNull,
            )
        }
        val phoneRows = report.entries.map { listOf(it.id, it.start.toInstant(), it.stop?.toInstant(), it.seconds, it.description, it.projectName, it.taskName) }
        assertEquals(webRows, phoneRows)
        android.util.Log.i("ScratchCheck", "rows=${phoneRows.size} first=${phoneRows.first()} last=${phoneRows.last()} rounded=${report.entries.count { it.seconds % 900 == 0L }}")
    }

    @Test
    fun offlineShowsTheSummarysMessageAndNoRows() {
        openDetailed()
        assertTrue(hasNode(hasText("Entry 0", substring = true)) || hasNode(hasText("Midnight", substring = true)))
        DeviceShell.run("cmd connectivity airplane-mode enable")
        awaitServer(false)
        // The next page fails: no rows remain.
