        assertEquals(ReportFailure.Unreachable, (state() as ReportsState.Failed).failure)
        assertNoRows()
        compose.onNode(hasText(string(R.string.reports_retry)) and hasClickAction()).performClick()
        compose.waitUntil("offline shows", LOAD_MS) { state() is ReportsState.Failed }
        assertTrue(hasNode(hasText(string(R.string.reports_offline_message))))
        assertNoRows()
        compose.onNode(androidx.compose.ui.test.hasContentDescription(string(R.string.reports_next_period))).performClick()
        compose.waitUntil("offline shows", LOAD_MS) { state() is ReportsState.Failed }
        assertNoRows()
    }

    @AtLargest
    @Test
    fun rowsFitAtTheLargestFontScale() {
        assertEquals(SystemFontScale.LARGEST, context.resources.configuration.fontScale)
        openDetailed()
        assertTextsFit()
        compose.onNode(hasScrollToIndexAction()).performScrollToIndex(20)
        assertTextsFit()
        for (node in compose.onAllNodes(hasClickAction()).fetchSemanticsNodes()) {
            val t = node.config.getOrNull(SemanticsProperties.Text)?.joinToString().orEmpty()
            val d = node.config.getOrNull(SemanticsProperties.ContentDescription)?.joinToString().orEmpty()
            assertTrue("unlabelled ${node.config}", t.isNotBlank() || d.isNotBlank())
        }
    }

    private fun assertNoRows() {
        for (i in 0 until 55) assertFalse("Entry $i shows offline", hasNode(hasText("Entry $i")))
        assertFalse(hasNode(hasText("Midnight")))
    }

    private fun assertTextsFit() {
        compose.waitForIdle()
        val width = context.resources.displayMetrics.widthPixels
        val texts = compose.onAllNodes(SemanticsMatcher.keyIsDefined(SemanticsProperties.Text), useUnmergedTree = true).fetchSemanticsNodes()
        for (node in texts) {
            val text = node.config.getOrNull(SemanticsProperties.Text)?.joinToString() ?: continue
            layout(node)?.let { assertFalse("cut off: $text", it.didOverflowHeight) }
            val left = node.positionOnScreen.x
            assertTrue("leaves width: $text", left >= -1 && left + node.size.width <= width + 1)
        }
    }

    private fun layout(node: SemanticsNode): TextLayoutResult? {
        val l = mutableListOf<TextLayoutResult>()
        node.config.getOrNull(SemanticsActions.GetTextLayoutResult)?.action?.invoke(l)
        return l.firstOrNull()
    }

    private fun openDetailed(): DetailedReport {
        scenario = ActivityScenario.launch(MainActivity::class.java)
        compose.waitUntil("app", LOAD_MS) { hasNode(hasText(string(R.string.reports))) }
        compose.onNode(hasText(string(R.string.reports)) and hasClickAction()).performClick()
        compose.waitUntil("summary", LOAD_MS) { state() is ReportsState.Loaded }
        compose.onNode(hasText(string(R.string.reports_tab_detailed)) and hasClickAction()).performClick()
        compose.waitUntil("detailed", LOAD_MS) { (state() as? ReportsState.Loaded)?.report is DetailedReport }
        compose.waitForIdle()
        return detailed()
    }

    private fun detailed(): DetailedReport = (state() as ReportsState.Loaded).report as DetailedReport

    private fun state(): ReportsState {
        var s: ReportsState? = null
        finishWithin("state") { scenario!!.onActivity { s = ViewModelProvider(it)[ReportsViewModel::class.java].model.state.value } }
        return s!!
    }

    private fun settings(): AccountSettings = app.accountSettings.state.value!!
    private fun hasNode(m: SemanticsMatcher) = compose.onAllNodes(m).fetchSemanticsNodes().isNotEmpty()
    private fun string(id: Int) = context.getString(id)

    private fun awaitServer(answers: Boolean) {
        if (!::account.isInitialized) return
        val deadline = System.nanoTime() + LOAD_MS * 1_000_000
        while (true) {
            val r = account.client.get(account.client.server.api("me"), JsonObject.serializer())
            if (((r as? ApiResult.Failure)?.error !is ApiError.Network) == answers) return
            check(System.nanoTime() < deadline)
            Thread.sleep(200)
        }
    }

    private class Seed(private val api: TogglApiClient) {
        val zone: ZoneId = ZoneId.of(ZONE)
        val today: LocalDate = LocalDate.now(zone)
        val weekStart: LocalDate = today.with(TemporalAdjusters.previousOrSame(DayOfWeek.WEDNESDAY))
        private val ws = api.get(api.server.api("me"), Ids.serializer()).orFail("me").defaultWorkspaceId

        init {
            api.send("PUT", api.server.api("me"), buildJsonObject { put("beginning_of_week", 3) }, JsonObject.serializer()).orFail("PUT me")
            api.send("PUT", api.server.api("workspaces", ws.toString()), buildJsonObject { put("rounding", 1); put("rounding_minutes", 15) }, JsonObject.serializer()).orFail("ws")
            api.send("POST", api.server.api("me", "preferences"), buildJsonObject { put("timeofday_format", "h:mm A") }, JsonObject.serializer()).orFail("prefs")
            val web = project("Website", "#06aaf5")
            val internal = project("Internal", "#990099")
            for (i in 0 until 55) {
                val day = minOf(weekStart.plusDays((i % 7).toLong()), today)
                entry(day.atTime(6, 0).plusMinutes(i * 10L), 300 + i * 7, "Entry $i", if (i % 3 == 0) null else if (i % 3 == 1) web else internal)
            }
            entry(today.atTime(0, 10), 600, "Midnight", web)
            entry(weekStart.minusDays(1).atTime(12, 0), 3600, "Outside", web)
        }

        private fun project(name: String, color: String): Long =
            api.send("POST", api.server.api("workspaces", ws.toString(), "projects"), buildJsonObject { put("name", name); put("color", color) }, Created.serializer()).orFail("project").id

        private fun entry(start: LocalDateTime, seconds: Int, description: String, project: Long?) {
            val body = buildJsonObject {
                put("workspace_id", ws); put("created_with", "scratch"); put("description", description)
                put("start", start.atZone(zone).toInstant().toString()); put("duration", seconds)
                if (project != null) put("project_id", project)
            }
            api.send("POST", api.server.api("workspaces", ws.toString(), "time_entries"), body, Created.serializer()).orFail("entry")
        }
    }

    @Serializable private class Ids(@SerialName("default_workspace_id") val defaultWorkspaceId: Long)
    @Serializable private class Created(val id: Long)

    private companion object {
        const val ZONE = "Pacific/Kiritimati"
        const val LOAD_MS = 30_000L
        const val TOTAL = 56
    }
}

@Target(AnnotationTarget.FUNCTION) @Retention(AnnotationRetention.RUNTIME) private annotation class AtLargest

private class Largest : TestRule {
    override fun apply(base: Statement, description: Description): Statement =
        if (description.getAnnotation(AtLargest::class.java) == null) base else SystemFontScale(SystemFontScale.LARGEST).apply(base, description)
}
