abstract class ScratchShots(private val dark: Boolean, scale: Float) {
    private val compose = createEmptyComposeRule()
    @get:Rule val rules: RuleChain = RuleChain.outerRule(SystemFontScale(scale)).around(compose)
    private val variant = "${if (dark) "dark" else "light"}-${(scale * 100).toInt()}"

    @Test
    fun detailed() {
        val state = ReportsState.Loaded(RangeSelection(WEEK, RangePreset.THIS_WEEK), DetailedReport(ENTRIES, nextRow = 51, loadingMore = false))
        shot("scratch-detailed", state, ReportTab.DETAILED)
    }

    private fun shot(name: String, state: ReportsState, tab: ReportTab) {
        ActivityScenario.launch(ComponentActivity::class.java).use { scenario ->
            scenario.onActivity {
                it.setContent {
                    TokklTheme(darkTheme = dark) {
                        ReportsContent(state, tab, ACCOUNT, ACCOUNT.time(TODAY), {}, {}, {}, {}, {}, {})
                    }
                }
            }
            compose.waitForIdle()
            ReferenceImages.assertMatches("$name-$variant", compose.onRoot().captureToImage())
        }
    }

    companion object {
        val ACCOUNT = AccountSettings(timeZone = "UTC", beginningOfWeek = DayOfWeek.MONDAY, timeResolutionMinutes = null)
        val TODAY: Clock = Clock.fixed(Instant.parse("2026-10-15T12:00:00Z"), ZoneOffset.UTC)
        val WEEK = ReportRange(LocalDate.of(2026, 10, 12), LocalDate.of(2026, 10, 18))
        private fun at(day: Int, h: Int, m: Int) = ZonedDateTime.of(2026, 10, day, h, m, 0, 0, ZoneId.of("UTC"))
        val ENTRIES = listOf(
            DetailedEntry(6, "Write the detailed report", "Tokkl for Android", "#0b83d9", "Reports", at(15, 9, 0), at(15, 11, 0), 7200),
            DetailedEntry(5, "", null, null, null, at(15, 8, 15), at(15, 9, 0), 2700),
            DetailedEntry(4, "Paint the north side", "Graffiti wall", "#d94182", null, at(14, 13, 30), at(14, 17, 30), 14400),
            DetailedEntry(3, "Code review", "Tokkl for Android", "#0b83d9", null, at(13, 23, 30), at(14, 0, 45), 4500),
            DetailedEntry(2, "Sketches", "Graffiti wall", "#d94182", null, at(13, 10, 0), at(13, 11, 15), 4500),
            DetailedEntry(1, "Plan the week", "Tokkl for Android", "#0b83d9", "Design", at(12, 9, 0), at(12, 12, 0), 10800),
        )
    }
}

class ScratchShotsLight : ScratchShots(dark = false, scale = 1f)
