        assertTrue((model.state.value as ReportsState.Loaded).report is SummaryReport)
        assertEquals(ReportRange(LocalDate.parse("2026-09-02"), LocalDate.parse("2026-09-08")), (model.state.value as ReportsState.Loaded).selection.range)
    }

    @Test
    fun aRowWithoutSevenDaysIsInvalidAndTiesSortByTitle() {
        weeklyBody = """[{"project_id":1,"project_name":"x","seconds":[1,2]}]"""
        model.selectTab(ReportTab.WEEKLY)
        model.open(); io.runAll()
        assertEquals(ReportFailure.Unexpected(null), (model.state.value as ReportsState.Failed).failure)
        val rows = listOf(
            WeeklyRow(2, "beta", null, List(7) { 0L }), WeeklyRow(1, "Alpha", null, List(7) { 0L }), WeeklyRow(3, "alpha", null, List(7) { 0L }),
        )
        assertEquals(listOf("alpha", "Alpha", "beta"), WeeklyReport.of(LocalDate.parse("2026-10-21"), rows).rows.map { it.title })
    }

    @Test
    fun weekRule() {
        val wed = DayOfWeek.WEDNESDAY
        val today = LocalDate.parse("2026-10-21")
        assertEquals(ReportRange(LocalDate.parse("2026-10-21"), LocalDate.parse("2026-10-27")), ReportRange(LocalDate.parse("2026-10-01"), LocalDate.parse("2026-10-31")).week(today, wed))
        assertEquals(ReportRange(LocalDate.parse("2026-09-30"), LocalDate.parse("2026-10-06")), ReportRange(LocalDate.parse("2026-10-01"), LocalDate.parse("2026-10-10")).week(today, wed))
    }

    private fun JsonObject.s(k: String) = getValue(k).jsonPrimitive.content
    private fun json(body: String) = MockResponse.Builder().code(200).body(body).addHeader("Content-Type", "application/json").build()

    private class Queued : CoroutineDispatcher() {
        private val queue = ArrayDeque<Runnable>()
        override fun dispatch(context: CoroutineContext, block: Runnable) { queue.addLast(block) }
        fun runAll() { while (queue.isNotEmpty()) queue.removeFirst().run() }
    }
}
