class TmpDiagTest {
    private val composeRule = createComposeRule()

    @get:Rule
    val rules: RuleChain = RuleChain.outerRule(SystemFontScale(SystemFontScale.LARGEST)).around(composeRule)

    @Test
    fun diag() {
        val variants = listOf(
            "base" to ClockTextStyle,
            "fixed" to ClockTextStyle.copy(lineHeight = 0.6.em, lineHeightStyle = LineHeightStyle(LineHeightStyle.Alignment.Center, LineHeightStyle.Trim.None, LineHeightStyle.Mode.Fixed)),
            "tight" to ClockTextStyle.copy(lineHeight = 0.6.em, lineHeightStyle = LineHeightStyle(LineHeightStyle.Alignment.Center, LineHeightStyle.Trim.None, LineHeightStyle.Mode.Tight)),
            "shift" to ClockTextStyle.copy(baselineShift = BaselineShift(0.6f)),
            "spacing" to ClockTextStyle.copy(letterSpacing = (-0.2).em),
        )
        val layouts = mutableMapOf<String, TextLayoutResult>()
        composeRule.setContent {
            Column {
                for ((name, style) in variants) {
                    Box(Modifier.testTag("h$name").background(Color.White).padding(16.dp)) {
                        Column(Modifier.width(320.dp)) {
                            Text(if (name == "fixed") "23:59:59 23:59:59 23:59:59" else "23:59:59", style = style, color = Color.Black,
                                modifier = Modifier.testTag(name), onTextLayout = { layouts[name] = it })
                        }
                    }
                }
            }
        }
        composeRule.waitForIdle()
        val out = StringBuilder()
        for ((name, _) in variants) {
            val host = composeRule.onNodeWithTag("h$name").fetchSemanticsNode().boundsInWindow
            val box = composeRule.onNodeWithTag(name).fetchSemanticsNode().boundsInWindow
            val px = composeRule.onNodeWithTag("h$name").captureToImage().toPixelMap()
            val bg = px[0, 0]
            var minX = Int.MAX_VALUE; var minY = Int.MAX_VALUE; var maxX = -1; var maxY = -1
            for (y in 0 until px.height) for (x in 0 until px.width) if (px[x, y] != bg) {
                minX = minOf(minX, x); minY = minOf(minY, y); maxX = maxOf(maxX, x); maxY = maxOf(maxY, y)
            }
            val l = layouts.getValue(name)
            out.append("\n$name box=(${box.left - host.left},${box.top - host.top})-(${box.right - host.left},${box.bottom - host.top}) ink=($minX,$minY)-($maxX,$maxY) size=${l.size} lines=${l.lineCount} ")
            for (i in 0 until l.lineCount) out.append("[${l.getLineTop(i)},${l.getLineBottom(i)},b${l.getLineBaseline(i)}]")
        }
        throw AssertionError("DIAG$out")
    }
}
