package com.github.e0ipso.tokkl.sifthold

import android.os.ParcelFileDescriptor
import android.os.SystemClock
import android.util.Log
import androidx.test.platform.app.InstrumentationRegistry
import org.junit.Test
import java.util.concurrent.TimeUnit

/** Scratch only: keeps the script's emulator up until the host creates a marker file, at most 30 min. */
class SiftHoldTest {
    @Test
    fun hold() {
        val ui = InstrumentationRegistry.getInstrumentation().uiAutomation
        fun sh(cmd: String): String =
            ParcelFileDescriptor.AutoCloseInputStream(ui.executeShellCommand(cmd)).use { it.readBytes().decodeToString() }
        val base = "/data/local/tmp/sift-w7-d3-hold"
        sh("rm -f $base-done")
        sh("touch $base-ready")
        Log.i("SiftHold", "ready: " + sh("ls -l $base-ready"))
        val deadline = SystemClock.elapsedRealtime() + TimeUnit.MINUTES.toMillis(30)
        while (SystemClock.elapsedRealtime() < deadline) {
            if (sh("ls $base-done").contains("$base-done")) break
            SystemClock.sleep(2_000)
        }
        sh("rm -f $base-ready $base-done")
        Log.i("SiftHold", "released")
    }
}
EOF
