import mockwebserver3.Dispatcher
import mockwebserver3.MockResponse
import mockwebserver3.MockWebServer
import mockwebserver3.RecordedRequest
import org.junit.After
import org.junit.Assert.assertEquals
import org.junit.Before
import org.junit.Test

/** Scratch: the clients model's archive against a MockWebServer. */
class ClientsModelScratchTest {
    private val server = MockWebServer()
    private val requests = CopyOnWriteArrayList<String>()
    private var refreshes = 0
    private lateinit var model: ClientsModel

    @Before
    fun setUp() {
        server.dispatcher = object : Dispatcher() {
            override fun dispatch(request: RecordedRequest): MockResponse {
                requests += "${request.method} ${request.url.encodedPath} ${request.body?.utf8()}"
                return when (request.url.encodedPath) {
                    "/api/v9/workspaces/7/clients" -> json("""[{"id":1,"wid":7,"name":"Acme","archived":false}]""")
                    "/api/v9/workspaces/7/projects" -> json("""[{"id":5,"client_id":1}]""")
                    "/api/v9/workspaces/7/clients/1/archive" -> json("[5]")
                    else -> MockResponse.Builder().code(404).build()
                }
            }
        }
        server.start()
        val url = ServerUrl.parse(server.url("/").toString())!!
        ConfiguredServer.readStoredFrom { url }
        ConfiguredTrust.readFrom(InMemoryServerTrust(url))
        model = ClientsModel(
[credential-related line omitted]
            workspaceId = { 7L },
            refreshCache = { refreshes++ },
            scope = CoroutineScope(Dispatchers.Unconfined),
            io = Dispatchers.Unconfined,
        )
    }

    @After
    fun tearDown() {
        server.close()
    }

    @Test
    fun archive() {
        model.open()
        val client = model.state.value.data!!.clients.single()
        assertEquals(1, model.state.value.data!!.projectCount(client))
        model.askToArchive(client)
        assertEquals(ClientsOverlay.ConfirmArchive(client), model.state.value.overlay)
        model.archive()
        println(requests)
        println(model.state.value)
        assertEquals(CatalogChange.Archived("Acme"), model.state.value.done)
        assertEquals(true, model.state.value.data!!.clients.single().archived)
        assertEquals(1, refreshes)
    }

    private fun json(body: String) = MockResponse.Builder().code(200).addHeader("Content-Type", "application/json").body(body).build()
}
