 */
private class SharedLabelSize(
    private val labels: List<String>,
    private val fontSize: TextUnit,
    private val fontScale: Float,
) : TextAutoSize {

    override fun TextAutoSizeLayoutScope.getFontSize(constraints: Constraints, text: AnnotatedString): TextUnit {
        val largest = fontSize.value
        val smallest = largest / fontScale.coerceAtLeast(1f)
        // Sizes in steps of STEP, from smallest (0) to largest (steps). Fitting only gets easier
        // as the size goes down, so a binary search finds the largest that fits.
        val steps = ((largest - smallest) / STEP).toInt()
        fun size(step: Int) = (smallest + step * STEP).sp
        fun allFit(step: Int) = labels.all { fits(performLayout(constraints, AnnotatedString(it), size(step))) }
        if (allFit(steps)) return fontSize
        var low = 0
        var high = steps - 1
        while (low < high) {
            val middle = (low + high + 1) / 2
            if (allFit(middle)) low = middle else high = middle - 1
        }
        return size(low)
    }

    private fun fits(layout: TextLayoutResult): Boolean = !layout.didOverflowWidth && !layout.didOverflowHeight

    override fun equals(other: Any?): Boolean =
        other is SharedLabelSize && labels == other.labels && fontSize == other.fontSize && fontScale == other.fontScale

    override fun hashCode(): Int = (labels.hashCode() * 31 + fontSize.hashCode()) * 31 + fontScale.hashCode()

    private companion object {
        /** In sp, as fine as TextAutoSize.StepBased's default step. */
        const val STEP = 0.25f
    }
}
